function projection(){
  const b=team;
  const projectionLabel=IS_PROMOTOR?'casais projetados':'atendimentos projetados';
  sc.innerHTML=`<div class="card pad sc"><div class="eye">CENÁRIO ATUAL</div><b class="c">${b}</b><span>${projectionLabel}</span></div><div class="card pad sc"><div class="eye">+10% PERFORMANCE</div><b class="v">${Math.round(b*1.1)}</b><span>${projectionLabel}</span></div><div class="card pad sc"><div class="eye">ALTA PERFORMANCE +25%</div><b class="g">${Math.round(b*1.25)}</b><span>${projectionLabel}</span></div>`;
  const p=get('psel');
  const targetTitle=document.getElementById('projectionTargetTitle');
  if(!IS_PROMOTOR){
    if(targetTitle)targetTitle.textContent='Leitura individual • '+AREA_LABEL;
    tg.innerHTML=[
      '<div class="card pad"><div class="eye">ATENDIMENTOS</div><b style="font-size:23px">'+p.c+'</b><span class="muted">'+(p.c/Math.max(p.d,1)).toFixed(1).replace('.',',')+' por dia ativo</span></div>',
      '<div class="card pad"><div class="eye">CONVERSÃO</div><b style="font-size:23px">'+pct(cv(p))+'</b><span class="muted">'+p.s+' vendas</span></div>',
      '<div class="card pad"><div class="eye">VGV</div><b style="font-size:23px">'+moneyFull(p.v)+'</b><span class="muted">'+moneyFull(p.v/Math.max(p.c,1))+' por atendimento</span></div>'
    ].join('');
    return;
  }
  if(targetTitle)targetTitle.textContent='Metas 22 → 35 → 50';
  tg.innerHTML=[22,35,50].map(t=>{
    const miss=Math.max(0,t-p.c),per=miss/R;
    return`<div class="card pad"><div class="eye">${t} CASAIS</div><b style="font-size:23px">${p.c} / ${t}</b><div class="prog"><i style="width:${Math.min(100,p.c/t*100)}%"></i></div><span class="muted">Faltam ${miss} • ${per.toFixed(1).replace('.',',')}/dia</span></div>`;
  }).join('');
}

function costs(){
  const c=S.gift/S.couples;
  ck.innerHTML=[
    k('Total gasto',moneyFull(S.gift),'brindes efetivos','a'),
    k('Brindes',S.gifts,'quantidade total','v'),
    k('Médio/brinde',moneyFull(S.gift/S.gifts),'custo unitário'),
    k('Custo/casal',moneyFull(c),'principal eficiência','g'),
    k('Custo/venda',moneyFull(S.gift/S.sales),'brindes ÷ vendas','a'),
    k('Custo/Q',moneyFull(S.gift/S.q),'brindes ÷ Q'),
    k('VGV/casal',moneyFull(S.vgv/S.couples),'resultado por casal','v'),
    k('Ticket médio',moneyFull(S.vgv/S.sales),'por venda','g')
  ].join('');
  const a=[...P].filter(p=>p.c).sort((x,y)=>co(x)-co(y)).slice(0,10);
  bars('cob',a.map(p=>[p.n,co(p)]),(v)=>moneyFull(v));
  ci.innerHTML=ins('Melhor eficiência',`${a[0].n}: ${moneyFull(co(a[0]))}/casal.`)+ins('Média da operação',`${moneyFull(c)}/casal.`)+ins('Controle','Valores calculados a partir dos brindes efetivos da base oficial.');
}

const FLOW_ORDER=['dash','rank','ind','fx','diag','perfil','proj','custos','gestao'];
const FLOW_LABEL={dash:'CENTRAL',rank:'RANKING',ind:'INDIVIDUAL',fx:'FX',diag:'DIAGNÓSTICO',perfil:'PERFIL',proj:'PROJEÇÕES',custos:'CUSTOS',gestao:'GESTÃO'};

const META={
  dash:['CENTRAL DE PERFORMANCE','RAIO X • Central','Onde estamos, onde podemos chegar e o que fazer hoje.'],
  rank:['COMPETITIVIDADE','Ranking de Performance','Resultado e projeção no mesmo lugar.'],
  ind:['PROFESSOR X','Performance Individual','Seu resultado transformado em ação.'],
  fx:['FX • FEEDBACK EXPERIENCE','Relatório de Performance','Constância, resultado, sinais diários e conclusão para uma conversa 1:1.'],
  diag:['DIAGNÓSTICO X','Central de Atenção','Somente sinais que exigem ação, acompanhamento ou correção.'],
  perfil:['INTELIGÊNCIA DE PERFIL','Perfil de Casais','Quem chega, quem compra e qual perfil gera resultado.'],
  proj:['FUTURO PROVÁVEL','Projeções','Ritmo atual, +10% e alta performance.'],
  gestao:['GESTÃO RAPHAEL BUENO','Gestão Raphael Bueno','Relatório executivo completo para reuniões.'],
  custos:['EFICIÊNCIA FINANCEIRA','Custo de Brinde','Quanto cada casal, Q e venda estão custando.']
};

function initAreaSelector(){
  const selArea=document.getElementById('areaSel');
  const current=document.getElementById('areaCurrent');
  if(current)current.textContent=AREA_LABEL;
  document.querySelectorAll('[data-area-link]').forEach(a=>a.classList.toggle('active',a.dataset.areaLink===AREA_KEY));
  document.querySelectorAll('[data-area-link]').forEach(a=>{const u=new URL(location.href);const k=a.dataset.areaLink;if(k==='promotor')u.searchParams.delete('area');else u.searchParams.set('area',k);a.href=u.pathname+u.search+u.hash;});
  const mainTitle=document.getElementById('pt');
  if(mainTitle)mainTitle.textContent='Performance • '+AREA_LABEL;
  if(!selArea)return;
  selArea.value=AREA_KEY;
  selArea.onchange=()=>{
    const next=selArea.value;
    if(current)current.textContent=AREA_LABELS[next]||AREA_LABEL;
    selArea.disabled=true;
    try{sessionStorage.setItem('sx-area-switch','1');}catch(_){}
    const url=new URL(location.href);
    if(next==='promotor')url.searchParams.delete('area'); else url.searchParams.set('area',next);
    url.searchParams.set('v','84');
    location.assign(url.toString());
  };
  try{if(sessionStorage.getItem('sx-area-switch')==='1'){if(location.hash!=='#home')cin.classList.add('hide');sessionStorage.removeItem('sx-area-switch');}}catch(_){}
  const statusHead=document.getElementById('rankStatusHead');
  if(statusHead)statusHead.textContent=IS_PROMOTOR?'22 casais':'Dias ativos';
  const topTitle=document.getElementById('topAreaTitle');
  if(topTitle)topTitle.textContent=IS_PROMOTOR?'Top captação do mês':'Top '+AREA_LABEL+' do mês';
}

function go(id){
  document.querySelectorAll('.sec').forEach(x=>x.classList.toggle('on',x.id===id));
  document.querySelectorAll('[data-go]').forEach(x=>x.classList.toggle('active',x.dataset.go===id));
  const m=META[id];eye.textContent=m[0];pt.textContent=(id==='dash'?'RAIO X • '+AREA_LABEL:m[1]);ps.textContent=m[2];
  const step=FLOW_ORDER.indexOf(id)+1;
  const fb=document.getElementById('flowBadge');
  if(fb)fb.textContent='ETAPA '+String(step).padStart(2,'0')+' DE '+String(FLOW_ORDER.length).padStart(2,'0')+' • '+FLOW_LABEL[id];
  window.scrollTo({top:0,behavior:'smooth'});
  if(location.hash!=='#home')history.replaceState(null,'',location.pathname+location.search+'#'+id);
  const activeBottom=document.querySelector('.bottom [data-go="'+id+'"]'); if(activeBottom)activeBottom.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});
}

document.querySelectorAll('[data-go]').forEach(b=>{b.onclick=e=>{e.preventDefault();e.stopPropagation();go(b.dataset.go);};});
rm.onchange=rank;
const opts=P.map(p=>`<option>${p.n}</option>`).join('');
sel.innerHTML=opts;psel.innerHTML=opts;
sel.onchange=individual;psel.onchange=projection;dsel.onchange=renderDiagnosis;
initAreaSelector();cinema();radar();dash();renderTodayOps();renderMetaPace();renderDailyEvolution();rank();individual();renderDiagnosis();profile();projection();costs();
if(location.hash==='#home'){cin.classList.remove('hide');cin.style.display='';window.scrollTo(0,0);}

